-- tools/run.sh --flavour forever tools/coefscheck.lua
--
-- T132 (docs/tasks/T132-forever-coefficients.md): Forever's +bonus estimate
-- from talentsforever's per-rank coefficients (Data/Coefs_Forever.lua,
-- generated by tools/buildcoefs.py; PRELIMINARY until verified in game).
--
--   1. the data file's shape: every row's numbers positive and finite, a name;
--      the druid's ranks below all present
--   2. through the real Book on the stub, the author's export (2026-10-23):
--      Rejuvenation R1-R4 0.80 each (20% x 4 ticks, 3 s measured); Healing
--      Touch R1-R4 0.429 / 0.571 / 0.714 / 0.857; Regrowth R2 0.286 + 0.071 x
--      7; Wrath R1 0.429; Moonfire R1 0.15 + 0.13 x 3 -- no sub-20 factor
--   3. a parsed tick period is used; 3 s only for the measured families, any
--      other tick row with no period on the old rule whole (M1), a channel
--      (Mind Flay) included (m2); no group rule on this path, the old path's kept (M2)
--      an either-or spell's heal and damage shares never summed (B1)
--   4. an id with no row falls back to the old rule with its old words
--   5. a measured share still wins over the generated estimate
--   (sections 1-5 run at player level 17, below every rank's level-penalty
--   start, so they hold the site's share alone -- T133's factors are 1 there)
--   6. T133 (docs/tasks/T133-forever-share-factors.md): Coef.LevelPenalty's
--      oracles; through the real Book at level 26 with Naturalist 5, each rank
--      inside the author's level-26 measured interval; the words of each
--      factor; ranks not read (said, review m1), a learn level unknown (said,
--      review m2), P on a hybrid (Regrowth R2 at 37), a rank above the rule,
--      two multipliers
--   7. T133 words: the card's estimated and measured lines, as predicted or
--      with the residual
HARNESS_FLAVOUR = "forever"

local here = arg[0]:match("^(.*)/[^/]+$")

local ok, fails = 0, {}
local function check(name, cond, detail)
    if cond then ok = ok + 1 else fails[#fails + 1] = name .. (detail and (" - " .. detail) or "") end
    print(string.format("%-72s %s%s", name, cond and "ok" or "FAIL", detail and (" - " .. detail) or ""))
end
local function T(name, fn)
    local good, cond, detail = pcall(fn)
    if not good then check(name, false, "raised: " .. tostring(cond)) return end
    check(name, cond == true, detail)
end

local a0 = arg[0]; arg[0] = here .. "/harness.lua"
local ST = dofile(here .. "/harness.lua")
arg[0] = a0

local S = _G.STUB
local Book = ST.Book
local Coef = ST.Coefficients
local W = ST.Words

-- T133: sections 1-5 hold the share alone; level 17 is below every start
S.level, ST.player.level = 17, 17

local function Near(a, b) return type(a) == "number" and type(b) == "number" and math.abs(a - b) < 1e-9 end

