local book = Book:Get()

local function Bonus(id)
    local e = book.spells[id]
    return e and e.bonus, e
end

--------------------------------------------------------------------------------
-- 1: the data file
--------------------------------------------------------------------------------
T("1 ST.CoefRules: every number positive and finite, every row named", function()
    local R = ST.CoefRules
    if type(R) ~= "table" then return false, "no ST.CoefRules" end
    local bad, n = {}, 0
    for id, r in pairs(R) do
        n = n + 1
        local where = tostring(id)
        if type(id) ~= "number" or id <= 0 or id ~= math.floor(id) then bad[#bad + 1] = where .. " id" end
        if type(r) ~= "table" then
            bad[#bad + 1] = where .. " row"
        else
            if r.direct == nil and r.heal == nil and r.tick == nil then bad[#bad + 1] = where .. " no share" end
            for _, k in ipairs({ "direct", "heal", "tick" }) do
                local v = r[k]
                if v ~= nil and (type(v) ~= "number" or v ~= v or v <= 0 or v == math.huge) then
                    bad[#bad + 1] = where .. " " .. k
                end
            end
            if type(r.name) ~= "string" or r.name == "" then bad[#bad + 1] = where .. " name" end
            if r.rank ~= nil and (type(r.rank) ~= "number" or r.rank < 1) then bad[#bad + 1] = where .. " rank" end
        end
    end
    return n > 0 and #bad == 0, n .. " rows; " .. table.concat(bad, "; ")
end)

T("1 the druid's ranks are there", function()
    local R = ST.CoefRules or {}
    local want = { 774, 1058, 1430, 2090, 5185, 5186, 5187, 5188, 8936, 8938, 8939, 5176, 8921 }
    local missing = {}
    for _, id in ipairs(want) do
        if type(R[id]) ~= "table" then missing[#missing + 1] = tostring(id) end
    end
    return #missing == 0, "missing " .. table.concat(missing, ", ")
end)

