--------------------------------------------------------------------------------
T("3 a parsed tick period is used: 2 s over 10 s is 5 ticks", function()
    local id = 774
    local e = { id = id, dur = 10, parsed = { heal = { tick = 20, period = 2, periodDur = 10 } } }
    local c, why = Coef.Estimate(e, "hot", "heal")
    return Near(c, 0.2 * 5) and why == "20% x 5 ticks, learn level unknown (talentsforever)", tostring(c) .. " " .. tostring(why)
end)

-- m2: a real channel, Mind Flay R1 (per-tick row, "over 3 sec." names no
-- period): no 3 s guess, the old channel rule with the reason
T("3 Mind Flay R1, a channel with no parsed period: the old channel rule", function()
    local e = { id = 15407, castKind = "channeled", interval = 3, dur = 3, level = 20,
        parsed = { damage = { over = 75, dur = 3 } } }
    local c, why = Coef.Estimate(e, "hot", "damage")
    return type(ST.CoefRules[15407]) == "table" and type(ST.CoefRules[15407].tick) == "number"
        and Near(c, 3 / 3.5) and why == "channel 3 s / 3.5 (tick period unknown -- old rule)",
        tostring(c) .. " " .. tostring(why)
end)

-- M2: the site's share is per target, so no group rule on this path
T("3 Prayer of Healing R1: 0.286, no group rule (the share is per target)", function()
    local e = { id = 596, targets = "party", cast = 3, parsed = { heal = { min = 312, max = 333 } } }
    local c, why = Coef.Estimate(e, "direct", "heal")
    return Near(c, 0.286) and why == "28.6%, learn level unknown (talentsforever)", tostring(c) .. " " .. tostring(why)
end)

T("3 the old path still halves a party heal", function()
    local e = { targets = "party", cast = 3, level = 30, parsed = { heal = { min = 312, max = 333 } } }
    local c, why = Coef.Estimate(e, "direct", "heal")
    return Near(c, 3 / 3.5 * Coef.GROUP) and why == "cast 3.0 / 3.5, group rule", tostring(c) .. " " .. tostring(why)
end)

-- B1: the site's "(direct)" is the damage part and "(heal)" the heal part;
-- an either-or spell gets the one its kind names, never the two summed
for _, c in ipairs({
    { 1311606, "Holy Shock R1", 0.429, "42.9%", 0.429, "42.9%" },
    { 15237, "Holy Nova R1", 0.107, "10.7%", 0.107, "10.7%" },
